// ===== 65 strategy cards (5 per Teil), shown once before the first attempt at a Teil. de + short English gloss.
const L9_STRAT={
 gL1:[["Erst die Aussagen, dann die Texte.","Read the 9 statements first, then the 4 posts."],["Lies jeden Beitrag einmal ganz und notiere am Rand die Nummern der Aussagen, die passen.","One pass per post; note matching statement numbers in the margin."],["Personen können mehrmals passen – eine Person kann auch dreimal vorkommen.","A person may be the answer several times."],["Achte auf Einschränkungen: „allerdings“, „trotzdem“, „nicht unbedingt“ drehen den Sinn.","Watch for qualifiers that flip meaning."],["18 Minuten: Nach 15 Minuten entscheidest du die offenen Aussagen und gehst weiter.","Budget 18 min; decide the leftovers at minute 15."]],
 gL2:[["Lies zuerst den ganzen Text ohne die Sätze – du brauchst den roten Faden.","Skim the whole text before the sentence bank."],["Schau dir die Wörter direkt vor und nach jeder Lücke an.","The sentence before and after each gap decides."],["Verweiswörter (dies, solche, dadurch, dort) müssen ein Ziel im Satz davor haben.","Reference words need a target in the previous sentence."],["Zwei Sätze passen nirgends – meist widersprechen sie dem Text.","Two sentences are distractors, usually contradicting the text."],["Hast du eine Lücke doppelt belegt, prüf zuerst die sicherere Lücke.","If two gaps want the same sentence, settle the safer one first."]],
 gL3:[["Die Fragen folgen der Reihenfolge des Textes.","Questions follow the order of the text."],["Lies die Frage, such die Stelle, formuliere die Antwort selbst – dann erst die Optionen.","Find the passage and answer in your own words first."],["Die richtige Option benutzt fast nie die Wörter des Textes, sondern ein Synonym.","The key paraphrases; the trap repeats words."],["Eine Option, die nur teilweise stimmt, ist falsch.","Half-true options are wrong."],["12 Minuten für 6 Fragen: zwei Minuten pro Frage.","Two minutes per question."]],
 gL4:[["Lies zuerst die Äußerungen, nicht die Überschriften.","Read the opinions before the headings."],["Fasse jede Äußerung in drei eigenen Wörtern zusammen.","Summarise each opinion in three words."],["Überschriften mit denselben Wörtern wie der Text sind oft Fallen.","Headings that repeat words are often traps."],["Zwei Überschriften bleiben übrig – du musst nicht alle benutzen.","Two headings stay unused."],["Entscheide nach der Hauptaussage, nicht nach einem Detail am Ende.","Match the main claim, not a side detail."]],
 gL5:[["Frag bei jedem Paragrafen: Worum geht es in ALLEN Sätzen?","What do all sentences of the paragraph share?"],["Einzelne Wörter wie „Schlüssel“ oder „Gebühr“ sind oft nur Nebenthemen.","Single words are often side topics."],["Amtsdeutsch: „ist zu tun“ = muss getan werden; „bedarf der Zustimmung“ = braucht Zustimmung.","Legal German: ist zu + infinitive = must."],["Vier Überschriften bleiben übrig.","Four headings stay unused."],["6 Minuten – das ist der kürzeste Teil. Nicht zu lange grübeln.","Shortest part: 6 minutes."]],
 gH1:[["Du hörst jeden Text nur einmal. Lies beide Aufgaben vorher genau.","Each text plays once; read both items first."],["Bei Richtig/Falsch: Hör auf Korrekturen – „nicht …, sondern …“.","Listen for corrections."],["Zahlen und Zeiten werden oft zweimal genannt; die zweite gilt.","The second number is usually the valid one."],["Kreuze sofort an und denk nicht über den letzten Text nach, wenn der nächste beginnt.","Mark at once, then let go."],["Unbekannte Wörter überhören – die Aufgabe fragt nach dem Kern.","Ignore unknown words; the item asks for the gist."]],
 gH2:[["Du hörst zweimal: Beim ersten Mal markieren, beim zweiten Mal kontrollieren.","Two plays: mark, then check."],["Die Fragen des Moderators kündigen die Antworten an.","The host's questions announce the answers."],["Trenne, was der Moderator vermutet, von dem, was der Gast sagt.","Separate the host's assumption from the guest's answer."],["Signale wie „ehrlich gesagt“, „allerdings“, „tatsächlich“ leiten die Lösung ein.","Signal words lead to the key."],["Die Fragen kommen in der Reihenfolge des Interviews.","Questions follow the interview order."]],
 gH3:[["Lerne in der Lesezeit die Namen und die Rollen der drei Personen.","Learn names and roles in the reading time."],["Notiere beim Hören nur M, 1 oder 2 neben die Aussage.","Note only M, 1 or 2."],["Die Moderatorin kann auch eine Lösung sein – meist eine oder zwei Aussagen.","The host is usually the answer once or twice."],["Achte darauf, wer etwas sagt, nicht wer zustimmt.","Who says it, not who agrees."],["Einmal hören: Lass eine Aussage offen und rate am Ende, statt den Faden zu verlieren.","One play: skip, guess at the end."]],
 gH4:[["Vortrag, zweimal: Die Gliederungssignale (erstens, zweitens) sind deine Karte.","Use the lecture's signposts."],["Lies in den 90 Sekunden alle acht Fragen und unterstreiche ein Schlüsselwort.","Underline one key word per question."],["Beispiele im Vortrag belegen meist eine Aussage – frag: wofür steht das Beispiel?","Ask what each example is meant to show."],["Achte auf „aber“, „dagegen“, „überraschend“ – dort kippt die Meinung.","Contrast words flip the view."],["Beim zweiten Hören nur noch die unsicheren Fragen prüfen.","Second play: check the unsure ones only."]],
 gS1:[["Plane fünf Minuten: ein Absatz pro Inhaltspunkt.","Plan five minutes; one paragraph per point."],["Deine Meinung gehört in den ersten Absatz – und noch einmal in den Schluss.","Opinion first and last."],["Beziehe dich auf den Gästebucheintrag, wenn es einen gibt.","Refer to the quoted post."],["Mindestens vier verschiedene Konnektoren: allerdings, außerdem, während, sodass.","Use at least four different connectors."],["Fünf Minuten Korrektur: Verb am Ende im Nebensatz, Nomen groß.","Proofread verb position and capitals."]],
 gS2:[["Anrede mit Titel und Name, danach klein weiter.","Formal salutation, then lower case."],["Alle vier Punkte – in einer sinnvollen Reihenfolge, nicht unbedingt in der vorgegebenen.","All four points in a sensible order."],["Bitten im Konjunktiv II: Wäre es möglich …? Könnten Sie …?","Requests in Konjunktiv II."],["Kein „Hallo“, kein „okay“, kein „Ich will“.","No casual register."],["Mit freundlichen Grüßen – ohne Komma – und darunter der Name.","Closing without comma, then the name."]],
 gSp1:[["Wähle in der ersten Minute ein Thema und bleib dabei.","Choose a topic in the first minute."],["Auf den Zettel nur Stichwörter und drei Übergangssätze.","Only key words and three transition sentences on the note."],["Kündige die Gliederung an: „Zuerst …, dann …, zum Schluss …“.","Announce your structure."],["Bei Punkt 2 wirklich ins Detail gehen – das ist der längste Teil.","Point 2 is the longest part."],["Bewerte am Ende selbst: „Alles in allem überwiegen für mich …“.","Close with your own judgement."]],
 gSp2:[["Nenne deine Position gleich im ersten Satz.","State your position at once."],["Jeder Beitrag beginnt mit einer Reaktion auf den Partner.","React first, then argue."],["Frag nach: „Wie meinen Sie das genau?“ – das zählt als Interaktion.","Asking back counts as interaction."],["Ein Beispiel aus deinem Alltag macht ein Argument stark.","Use a personal example."],["Wenn der Prüfer „zum Schluss“ sagt: in zwei Sätzen zusammenfassen, dafür oder dagegen.","Summarise in two sentences when asked."]]};
